10		"github.com/entireio/entire-brain/factmerge"
11		"github.com/entireio/entire-brain/internal/apiurl"
12		"github.com/entireio/entire-brain/internal/factsync"
13	)
14	
15	// hostEntireBinary is the host CLI the plugin shells out to; PATH comes from
16	// the caller's environment (the daemon plist bakes PATH at install time).
17	const hostEntireBinary = "entire"
18	
19	// hostedFactsSyncAndPull closes the hosted-memory loop for one branch: publish
20	// the branch's local facts through factsync.Sync (read-merge-CAS), record the
21	// per-branch hosted target, then merge the settled head — with server-stamped
22	// authors — back into the local branch store so teammates' facts become
23	// first-class in brief/recall.
24	//
25	// It is a NEVER-FAILS step: every gated or soft failure is one stderr line and
26	// a nil return, because its callers (daemon tick, session-end hook, connect)
27	// must not fail on hosted outages. The error return exists for programming
28	// errors only.
29	//
30	// Gate order is fixed: (1) the local-only kill switch always wins; (2) the
31	// repo binding is the connection state — absent, each run tries to resolve it
32	// through the host CLI and falls back to local-only, silently, until that
33	// succeeds; (3) apiurl.Validate before any client exists. A fresh token is
34	// minted per call via the host CLI's own login and held only in memory.
35	func hostedFactsSyncAndPull(ctx context.Context, errW io.Writer, opts Options, repoDir string, storage repoStorage, branch string) error {
36		if brainNoEgressMode() {
37			return nil
38		}
39		binding, present, err := readHostedRepoBinding(storage.BrainDir)
40		if err != nil {
41			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
42			return nil
43		}
44		if !present {
45			// Auto-connect: placement comes from the host CLI (whereami), which
46			// fails for a logged-out user, an unregistered repo, or a CLI without
47			// the command — all of which mean "stay local and retry next run".
48			// ponytail: an unresolvable repo re-runs whereami on every throttled
49			// sync attempt; cache a negative result if that ever gets expensive.
50			resolved, whereamiErr := resolveWhereami(ctx, opts.Runner, repoDir)
51			if whereamiErr != nil {
52				return nil
53			}
54			binding, err = bindHostedRepo(storage.BrainDir, resolved.RepoID, resolved.APIURL)
55			if err != nil {
56				fmt.Fprintf(errW, "hosted sync: auto-connect skipped: %v\n", err)
57				return nil
58			}
59		}
60		baseURL, err := apiurl.Validate(binding.BaseURL)
61		if err != nil {
62			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
63			return nil
64		}
65		token, err := mintHostedToken(ctx, opts.Runner, repoDir, hostEntireBinary)
66		if err != nil {
67			fmt.Fprintf(errW, "hosted sync: skipped: %v\n", err)
68			return nil
69		}
70	
71		facts, err := loadFacts(storage.BrainDir, branch)
72		if err != nil {
73			fmt.Fprintf(errW, "hosted sync: branch %s: %v\n", branch, err)
74			return nil
75		}
76		srv := &factsync.HTTPServer{BaseURL: baseURL, Token: token}
77		memberID := resolveSyncMemberID(ctx, opts.Runner, repoDir, "")
78		res, err := factsync.Sync(ctx, srv, binding.RepoID, branch, memberID, facts, opts.Now().UTC())
79		if err != nil {
80			// Publish can be denied (missing push grant, 5xx) while the pull grant
81			// works; discarding the readable head would starve this member of the
82			// team's facts — the receive half of the loop. Pull-only: no marker
83			// (the branch did not sync), no proposals, head verified fail-closed.
84			fmt.Fprintf(errW, "hosted sync: branch %s publish failed (local brain unaffected): %v; attempting pull-only\n", branch, err)
85			pullOnlyHostedFacts(ctx, errW, opts, storage, srv, binding.RepoID, branch)
86			return nil
87		}
88		// The per-branch marker records that this branch has synced against this
89		// target; the blind-spot note keys off its absence.
90		if err := writeHostedFactsBinding(storage.BrainDir, branch, binding.RepoID, baseURL); err != nil {
91			fmt.Fprintf(errW, "hosted sync: record hosted target: %v\n", err)
92		}
93		// Promote raises a keep-both conflict proposal only on FIRST contact (both
94		// facts are in the head afterwards), so dropping res.Proposals here would
95		// lose the review signal forever. Persist to the local review queue like
96		// the manual sync; v1 cuts the hosted queue endpoints, so no publish.
97		if err := persistFactsSyncProposals(storage.BrainDir, branch, res.Proposals); err != nil {
98			fmt.Fprintf(errW, "hosted sync: persist raised conflicts: %v\n", err)
99		}
100	
101		// Best-effort attribution: the authors map is additive on the GET response,
102		// so a second read is the only way to fetch it. Failure costs display
103		// attribution, never the pull.
104		var authors map[string]string
105		if _, _, a, found, authorsErr := srv.CurrentWithAuthors(ctx, binding.RepoID, branch); authorsErr == nil && found {
106			authors = a
107		}
108		// The server map is the only attribution source: it overwrites whatever
109		// the blob carried (SanitizeForEgress clears Author on upload, but an old
110		// or hostile peer's value must not survive either). Records absent from
111		// the map arrive unattributed, and Upsert keeps any handle already stored.
112		merged := append([]factmerge.Record(nil), res.Facts...)
113		for i := range merged {
114			merged[i].Author = authors[merged[i].ID]
115		}
116	
117		if mergeHostedFactsIntoLocal(errW, opts, storage, branch, merged) {
118			fmt.Fprintf(errW, "hosted sync: branch %s published=%v attempts=%d facts=%d\n", branch, res.Published, res.Attempts, len(res.Facts))
119		}
120		return nil
121	}
122	
123	// pullOnlyHostedFacts is the degraded receive path when publish failed: read
124	// the head, verify it fail-closed exactly like Sync does, stamp attribution,
125	// and merge it into the local store. Deliberately NOT written: the per-branch
126	// marker (this branch has not synced, so the blind-spot note keeps firing)
127	// and proposals (no merge ran, none were raised).
128	func pullOnlyHostedFacts(ctx context.Context, errW io.Writer, opts Options, storage repoStorage, srv *factsync.HTTPServer, repoID, branch string) {
129		_, plaintext, authors, found, err := srv.CurrentWithAuthors(ctx, repoID, branch)
130		if err != nil {
131			fmt.Fprintf(errW, "hosted sync: branch %s pull-only read failed: %v\n", branch, err)
132			return
133		}
134		if !found || len(plaintext) == 0 {
135			return
136		}
137		head, err := factmerge.ParseNDJSON(bytes.NewReader(plaintext))
138		if err != nil {
139			fmt.Fprintf(errW, "hosted sync: branch %s pull-only parse failed: %v\n", branch, err)
140			return
141		}
142		// Same fail-closed rule as Sync: a head record whose content id does not
143		// re-derive is a forgery and nothing from that head may be merged.
144		if err := factmerge.VerifyIdentities(head); err != nil {
145			fmt.Fprintf(errW, "hosted sync: branch %s pull-only refused untrustworthy head: %v\n", branch, err)
146			return
147		}
148		for i := range head {
149			head[i].Author = authors[head[i].ID]
150		}
151		if mergeHostedFactsIntoLocal(errW, opts, storage, branch, head) {
152			fmt.Fprintf(errW, "hosted sync: branch %s pull-only facts=%d (local facts not shared)\n", branch, len(head))
153		}
154	}
155	
156	// mergeHostedFactsIntoLocal writes a verified hosted fact set into the local
157	// branch store with the import write composition: everything under one write
158	// lock, manifest refresh included; a manifest failure reports alongside the
159	// successful pull instead of masking it. upsertFact never moves a local
160	// status, so a locally retracted fact stays retracted whatever the head says.
161	// The head is authoritative for RETIREMENTS, though: a non-active head status
162	// is a settled retraction/supersession and must reach the local store.
163	// Lifecycle moves one way — active to retired, never a revival.
164	func mergeHostedFactsIntoLocal(errW io.Writer, opts Options, storage repoStorage, branch string, merged []factmerge.Record) bool {
165		var manifestErr error
166		if err := withBrainWriteLock(storage.BrainDir, func() error {
167			existing, loadErr := loadFacts(storage.BrainDir, branch)
168			if loadErr != nil {
169				return loadErr
170			}
171			for _, fact := range merged {
172				existing = upsertFact(existing, fact)
173				if fact.Status == factStatusActive {
174					continue
175				}
176				if i := indexOfFact(existing, fact.ID); i >= 0 && existing[i].Status == factStatusActive {
177					existing[i].Status = fact.Status
178					existing[i].SupersededBy = fact.SupersededBy
179					existing[i].UpdatedAt = opts.Now().UTC()
180				}
181			}
182			if err := writeFacts(storage.BrainDir, branch, existing); err != nil {
183				return err
184			}
185			manifestErr = updateFactSourceManifestLocked(storage.BrainDir, opts.Now().UTC())
186			return nil
187		}); err != nil {
188			fmt.Fprintf(errW, "hosted sync: branch %s pull failed (local store unchanged): %v\n", branch, err)
189			return false
190		}
191		if manifestErr != nil {
192			fmt.Fprintf(errW, "hosted sync: facts updated, but the source manifest could not be refreshed: %v\n", manifestErr)
193		}
194		return true
195	}
196	
197	// hostedSyncBranch resolves the branch a hosted sync step should cover: the
198	// repo's current branch, else the default branch.
199	func hostedSyncBranch(ctx context.Context, runner CommandRunner, repoDir string) string {
200		if current, err := gitScalar(ctx, runner, repoDir, "branch", "--show-current"); err == nil {
201			if branch := strings.TrimSpace(current); branch != "" {
202				return branch
203			}
204		}
205		return distillDefaultBranch
206	}
