9	// hostedRepoBinding is the repo-level "connected to a hosted brain" marker,
10	// written once by `entire brain connect`. Only non-secrets live here; tokens
11	// are minted per call (see mintHostedToken). The per-branch
12	// hosted-target.json (hostedFactsBinding) records which branches have synced.
13	type hostedRepoBinding struct {
14		RepoID  string `json:"repo_id"`
15		BaseURL string `json:"base_url"`
16	}
17	
18	const hostedRepoBindingFile = "hosted.json"
19	
20	func writeHostedRepoBinding(brainDir string, binding hostedRepoBinding) error {
21		binding.BaseURL = strings.TrimRight(binding.BaseURL, "/")
22		data, err := json.Marshal(binding)
23		if err != nil {
24			return err
25		}
26		return withBrainWriteLock(brainDir, func() error {
27			return writeBrainRelativeFileAtomic(brainDir, hostedRepoBindingFile, append(data, '\n'), 0600)
28		})
29	}
30	
31	func readHostedRepoBinding(brainDir string) (hostedRepoBinding, bool, error) {
32		var binding hostedRepoBinding
33		data, present, err := readMemoryStateFile(brainDir, hostedRepoBindingFile, "hosted repo binding", defaultMaxReadBytes)
34		if err != nil || !present {
35			return binding, false, err
36		}
37		if err := json.Unmarshal(data, &binding); err != nil {
38			return binding, false, fmt.Errorf("invalid hosted repo binding: %w", err)
39		}
40		binding.BaseURL = strings.TrimRight(binding.BaseURL, "/")
41		return binding, true, nil
42	}
