80			t.Fatal(err)
81		}
82	
83		// The docs layer is now dead: prove retrieval really cannot answer from it
84		// before asserting what status must say about it.
85		//
86		// This step used to assert that `search` SUCCEEDED and returned nothing,
87		// which is what the docs arm did at the time: loadDocIndex's os.IsNotExist
88		// was skipped rather than raised. That silent skip is the defect this test's
89		// own comment describes, and it is now fixed — a doc index the manifest
90		// DECLARES and the store does not hold is refused by name. The assertion
91		// that matters here is unchanged (the removed record must not come back);
92		// only the shape of "cannot answer" moved from an empty result to an error.
93		out, err := execute(t, NewRootCommand(opts), "search", "postgres")
94		if err == nil {
95			t.Fatalf("search answered over a docs index that is gone:\n%s", out)
96		}
97		if strings.Contains(out, "doc:doc-1") {
98			t.Fatalf("search still returned the doc record after the index was removed:\n%s", out)
99		}
100		if !strings.Contains(err.Error(), docIndexPath) {
101			t.Fatalf("search does not name the absent index: %v", err)
102		}
103	
104		degraded, err := buildAvailableBrainStatusReport(context.Background(), opts, repoDir)
105		if err != nil {
106			t.Fatalf("degraded status: %v", err)
107		}
108		if degraded.Retrieval == nil || degraded.Retrieval.Freshness == nil {
109			t.Fatalf("degraded status has no retrieval freshness: %+v", degraded.Retrieval)
110		}
111		axis := degraded.Retrieval.Freshness.Axes["docs"]
112		if axis.State == "ok" {
113			t.Fatalf("docs axis still reports ok while %s is absent: %+v", docIndexPath, axis)
114		}
115		if axis.State != "missing" {
116			t.Fatalf("docs axis state = %q, want missing: %+v", axis.State, axis)
117		}
118		if !strings.Contains(axis.Detail, docIndexPath) {
119			t.Fatalf("docs axis detail does not name the absent index: %q", axis.Detail)
120		}
121		if got := degraded.Retrieval.Freshness.Severity; got == "ok" {
122			t.Fatalf("retrieval freshness severity = %q while the docs layer is dead", got)
123		}
124	
125		// The CLI surface must carry the same signal as the in-process report.
126		statusOut, err := execute(t, NewRootCommand(opts), "status")
127		if err != nil {
128			t.Fatalf("status: %v\n%s", err, statusOut)
